(()=>{
const D=window.RefZoneData,app=document.getElementById('app'),toast=document.getElementById('toast');
const store={get(k,f=null){try{return JSON.parse(localStorage.getItem('rz:'+k))??f}catch{return f}},set(k,v){localStorage.setItem('rz:'+k,JSON.stringify(v))}};
const savedMemberships=store.get('memberships');if(Array.isArray(savedMemberships)&&savedMemberships.length===D.memberships.length)D.memberships.splice(0,D.memberships.length,...savedMemberships);
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const route=(p)=>location.hash='#/'+p.replace(/^\//,'');
const showToast=m=>{toast.textContent=m;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)};
const getTrack=id=>D.tracks.find(t=>t.id===id)||D.tracks[0],getPath=id=>D.pathways.find(p=>p.id===id)||D.pathways[0];
const getCourseUI=(trackId,pathId)=>{if(trackId==='nfhs'&&pathId==='foundations')return window.NFHSCourseUI||null;if(trackId==='nfhs'&&pathId==='advancement')return window.NFHSAdvancementCourseUI||null;if(trackId==='nfhs'&&pathId==='elite')return window.NFHSEliteCourseUI||null;if(trackId==='njcaa-men'&&pathId==='foundations')return window.NJCAAMenCourseUI||null;if(trackId==='njcaa-men'&&pathId==='advancement')return window.NJCAAMenAdvancementCourseUI||null;if(trackId==='njcaa-men'&&pathId==='elite')return window.NJCAAMenEliteCourseUI||null;if(trackId==='njcaa-women'&&pathId==='foundations')return window.NJCAAWomenCourseUI||null;if(trackId==='njcaa-women'&&pathId==='advancement')return window.NJCAAWomenAdvancementCourseUI||null;if(trackId==='njcaa-women'&&pathId==='elite')return window.NJCAAWomenEliteCourseUI||null;if(trackId==='naia-women'&&pathId==='foundations')return window.NAIAWomenCourseUI||null;if(trackId==='naia-women'&&pathId==='advancement')return window.NAIAWomenAdvancementCourseUI||null;if(trackId==='naia-women'&&pathId==='elite')return window.NAIAWomenEliteCourseUI||null;if(trackId==='naia-men'&&pathId==='foundations')return window.NAIAMenCourseUI||null;if(trackId==='naia-men'&&pathId==='advancement')return window.NAIAMenAdvancementCourseUI||null;if(trackId==='naia-men'&&pathId==='elite')return window.NAIAMenEliteCourseUI||null;if(trackId==='ncaa-d3-men'&&pathId==='foundations')return window.NCAAD3MenCourseUI||null;if(trackId==='ncaa-d3-men'&&pathId==='advancement')return window.NCAAD3MenAdvancementCourseUI||null;if(trackId==='ncaa-d3-men'&&pathId==='elite')return window.NCAAD3MenEliteCourseUI||null;if(trackId==='ncaa-d3-women'&&pathId==='foundations')return window.NCAAD3WomenCourseUI||null;if(trackId==='ncaa-d3-women'&&pathId==='advancement')return window.NCAAD3WomenAdvancementCourseUI||null;if(trackId==='ncaa-d3-women'&&pathId==='elite')return window.NCAAD3WomenEliteCourseUI||null;if(trackId==='ncaa-d2-men'&&pathId==='foundations')return window.NCAAD2MenCourseUI||null;if(trackId==='ncaa-d2-men'&&pathId==='advancement')return window.NCAAD2MenAdvancementCourseUI||null;if(trackId==='ncaa-d2-men'&&pathId==='elite')return window.NCAAD2MenEliteCourseUI||null;if(trackId==='ncaa-d2-women'&&pathId==='foundations')return window.NCAAD2WomenCourseUI||null;if(trackId==='ncaa-d2-women'&&pathId==='advancement')return window.NCAAD2WomenAdvancementCourseUI||null;if(trackId==='ncaa-d2-women'&&pathId==='elite')return window.NCAAD2WomenEliteCourseUI||null;if(trackId==='ncaa-d1-men'&&pathId==='foundations')return window.NCAAD1MenCourseUI||null;if(trackId==='ncaa-d1-men'&&pathId==='advancement')return window.NCAAD1MenAdvancementCourseUI||null;if(trackId==='ncaa-d1-men'&&pathId==='elite')return window.NCAAD1MenEliteCourseUI||null;if(trackId==='ncaa-d1-women'&&pathId==='foundations')return window.NCAAD1WomenCourseUI||null;if(trackId==='ncaa-d1-women'&&pathId==='advancement')return window.NCAAD1WomenAdvancementCourseUI||null;if(trackId==='ncaa-d1-women'&&pathId==='elite')return window.NCAAD1WomenEliteCourseUI||null;if(trackId==='usa-men'&&pathId==='foundations')return window.USAMenCourseUI||null;if(trackId==='usa-men'&&pathId==='advancement')return window.USAMenAdvancementCourseUI||null;if(trackId==='usa-men'&&pathId==='elite')return window.USAMenEliteCourseUI||null;if(trackId==='usa-women'&&pathId==='foundations')return window.USAWomenCourseUI||null;if(trackId==='usa-women'&&pathId==='advancement')return window.USAWomenAdvancementCourseUI||null;if(trackId==='usa-women'&&pathId==='elite')return window.USAWomenEliteCourseUI||null;if(trackId==='euro-men'&&pathId==='foundations')return window.EuroLeagueMenCourseUI||null;if(trackId==='euro-men'&&pathId==='advancement')return window.EuroLeagueMenAdvancementCourseUI||null;if(trackId==='euro-men'&&pathId==='elite')return window.EuroLeagueMenEliteCourseUI||null;if(trackId==='euro-women'&&pathId==='foundations')return window.EuroLeagueWomenCourseUI||null;if(trackId==='euro-women'&&pathId==='advancement')return window.EuroLeagueWomenAdvancementCourseUI||null;if(trackId==='euro-women'&&pathId==='elite')return window.EuroLeagueWomenEliteCourseUI||null;if(trackId==='fiba-men'&&pathId==='foundations')return window.FIBAMenCourseUI||null;if(trackId==='fiba-men'&&pathId==='advancement')return window.FIBAMenAdvancementCourseUI||null;if(trackId==='fiba-men'&&pathId==='elite')return window.FIBAMenEliteCourseUI||null;if(trackId==='fiba-women'&&pathId==='foundations')return window.FIBAWomenCourseUI||null;if(trackId==='fiba-women'&&pathId==='advancement')return window.FIBAWomenAdvancementCourseUI||null;if(trackId==='fiba-women'&&pathId==='elite')return window.FIBAWomenEliteCourseUI||null;if(trackId==='g-league'&&pathId==='foundations')return window.GLeagueCourseUI||null;if(trackId==='g-league'&&pathId==='advancement')return window.GLeagueAdvancementCourseUI||null;if(trackId==='g-league'&&pathId==='elite')return window.GLeagueEliteCourseUI||null;if(trackId==='wnba'&&pathId==='foundations')return window.WNBACourseUI||null;if(trackId==='wnba'&&pathId==='advancement')return window.WNBAAdvancementCourseUI||null;if(trackId==='wnba'&&pathId==='elite')return window.WNBAEliteCourseUI||null;if(trackId==='nba'&&pathId==='foundations')return window.NBACourseUI||null;if(trackId==='nba'&&pathId==='advancement')return window.NBAAdvancementCourseUI||null;if(trackId==='nba'&&pathId==='elite')return window.NBAEliteCourseUI||null;return null};
const trackIcon=(t,className='')=>t.icon?`<img class="${className}" src="${esc(t.icon)}" alt="${esc(t.name)} RefZone University course icon" loading="lazy" decoding="async">`:`<span class="${className} pathway-icon-fallback" role="img" aria-label="${esc(t.name)} icon not supplied">DI W</span>`;
function shell(title,content,eyebrow='REFZONE UNIVERSITY'){return `<section class="page"><div class="content-header"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1></div>${content}</section>`}
function home(){
const pathwayCards=[
  {id:'foundations',tone:'bachelor',icon:'assets/degree-icons/refzone-bachelors-courses.png',label:'Bachelor’s Degree Structure',title:'Professional Foundations',description:'A four-year sequence in rules, mechanics, judgment, communication, film, practicum, and capstone work.',count:'24 Courses · 120 Units'},
  {id:'advancement',tone:'masters',icon:'assets/degree-icons/refzone-masters-courses.png',label:'Master’s Degree Structure',title:'Advanced Officiating',description:'A two-year graduate sequence in advanced judgment, replay, leadership, evaluation, film defense, and practicum.',count:'12 Courses · 36 Units'},
  {id:'elite',tone:'phd',icon:'assets/degree-icons/refzone-phd-courses.png',label:'PhD Degree Structure',title:'Research & Leadership',description:'A doctoral sequence in decision science, research, governance, evaluation, technology, policy, and original contribution.',count:'20 Courses · 60 Units'}
].map(p=>`<article class="rzu-reference-tier-card rzu-reference-tier-card--${p.tone}">
  <a class="rzu-reference-tier-card__main" href="#/program/nfhs/${p.id}" aria-label="Explore the ${p.label} ${p.title} pathway">
    <div class="rzu-reference-degree-visual" aria-hidden="true"><img class="rzu-reference-degree-icon-image" src="${p.icon}" alt="" loading="lazy" decoding="async"></div>
    <div class="rzu-reference-tier-copy">
      <p>${p.label}</p>
      <h3>${p.title}</h3>
      <span>${p.description}</span>
    </div>
  </a>
  <div class="rzu-reference-tier-card__footer"><strong>${p.count}</strong></div>
</article>`).join('');
const trackPathways=D.tracks.map((t,index)=>`<article class="rzu-track-card"><div class="rzu-track-card__top"><div class="rzu-track-card__icon-shell">${trackIcon(t,'rzu-track-card__icon')}</div><div class="rzu-track-card__number">${String(index+1).padStart(2,'0')}</div></div><div class="rzu-track-card__head"><p>${t.group}</p><h3>${t.name}</h3><span>${t.category} rules category</span></div><div class="rzu-track-card__links">${D.pathways.map(p=>`<a href="#/program/${t.id}/${p.id}"><span>${p.short}</span><small>${p.id==='foundations'?'Start':p.id==='advancement'?'Advance':'Lead'}</small></a>`).join('')}</div></article>`).join('');
const membershipStrip=D.memberships.map(m=>`<article class="rzu-membership-card"><p>${m.name}</p><div class="rzu-membership-price"><strong>$${m.monthly}</strong><span>/month</span></div><span>${m.intended}</span><a href="index.html#membership-access">View access <b aria-hidden="true">→</b></a></article>`).join('');
return `<div class="rzu-home">
<section class="rzu-hero rzu-hero--reference" aria-labelledby="rzu-title"><div class="rzu-hero__arena" aria-hidden="true"></div><div class="rzu-shell rzu-hero__inner"><div class="rzu-hero__copy"><p class="rzu-eyebrow">REFZONE UNIVERSITY</p><h1 id="rzu-title"><span>THE ULTIMATE EDUCATION.</span><strong>THE ULTIMATE OFFICIAL.</strong></h1><p class="rzu-hero__lead">Twenty competition levels.&nbsp;&nbsp; Three degree-structured programs at every level.</p><p class="rzu-hero__body">RefZone University is the most comprehensive officiating<br>education platform in the world - built by the game,<br>for the game. Whether you’re just starting out or<br>aiming for the highest levels of professional<br>basketball, our curriculum gives you the<br>knowledge, confidence, and credibility<br>to rise above.</p><div class="rzu-hero__actions"><a class="rzu-button rzu-button--primary" href="#/placement">TAKE THE ELIGIBILITY SURVEY <span aria-hidden="true">→</span></a></div></div><div class="rzu-hero__visual"><img src="assets/hero/refzone-hero-logo.png" alt="RefZone University logo" decoding="async" fetchpriority="high"></div></div></section>
<section class="rzu-reference-stats" aria-label="RefZone University overview"><div class="rzu-shell rzu-reference-stats__grid"><article><div class="rzu-reference-stat-icon" aria-hidden="true"><svg viewBox="0 0 64 64" preserveAspectRatio="xMidYMid meet"><path d="M7 25 32 12l25 13-25 13L7 25Z"/><path d="M16 31v15c9 7 23 7 32 0V31"/><path d="M57 26v19"/><circle cx="57" cy="48" r="2"/></svg></div><div class="rzu-reference-stat-copy"><b>20</b><div><strong>Competition Tracks</strong><p>Built for Every Official</p></div></div></article><article><div class="rzu-reference-stat-icon" aria-hidden="true"><svg viewBox="0 0 64 64" preserveAspectRatio="xMidYMid meet"><path d="m10 22 22-12 22 12-22 12-22-12Z"/><path d="m10 31 22 12 22-12"/><path d="m10 40 22 12 22-12"/></svg></div><div class="rzu-reference-stat-copy"><b>60</b><div><strong>Degree-Structured Programs</strong><p>Bachelor’s, Master’s &amp; PhD at all 20 levels</p></div></div></article><article><div class="rzu-reference-stat-icon" aria-hidden="true"><svg viewBox="0 0 64 64" preserveAspectRatio="xMidYMid meet"><path d="M32 7c8 7 16 9 24 10v14c0 13-8 22-24 27C16 53 8 44 8 31V17c8-1 16-3 24-10Z"/><path d="m32 21 3.3 6.7 7.4 1.1-5.4 5.2 1.3 7.4-6.6-3.5-6.6 3.5 1.3-7.4-5.4-5.2 7.4-1.1L32 21Z"/></svg></div><div class="rzu-reference-stat-copy"><b>4</b><div><strong>Curated Track Groups</strong><p>Connected multi-ruleset study routes</p></div></div></article><article><div class="rzu-reference-stat-icon" aria-hidden="true"><svg viewBox="0 0 64 64" preserveAspectRatio="xMidYMid meet"><circle cx="32" cy="32" r="25"/><path d="M7 32h50M32 7c9 8 14 16 14 25S41 49 32 57M32 7c-9 8-14 16-14 25s5 17 14 25M12 19h40M12 45h40"/></svg></div><div class="rzu-reference-stat-copy"><b>1</b><div><strong>Unified Learning System</strong><p>Rules, mechanics, film, leadership and research</p></div></div></article></div></section>
<section class="rzu-reference-curriculum rzu-transition" id="pathways" aria-labelledby="rzu-curriculum-title"><div class="rzu-shell"><header class="rzu-reference-curriculum__heading"><p>Built Like a Degree. Designed for Officials.</p><h2 id="rzu-curriculum-title">A Curriculum That Builds Legacy</h2><span>Every competition level contains a complete Bachelor’s, Master’s, and PhD degree structure. Each program has its own admission gates, academic terms, course codes, credit-equivalent units, assessments, practicums, capstone or dissertation requirements, and completion standards.</span></header><div class="rzu-reference-tier-grid">${pathwayCards}</div><div class="rzu-reference-curriculum__action"><a class="rzu-reference-curriculum__button" href="#/catalog">View All 20 Tracks <span aria-hidden="true">→</span></a></div></div></section>
<section class="rzu-memberships rzu-transition" aria-labelledby="rzu-memberships-title"><div class="rzu-shell"><header class="rzu-section-heading rzu-section-heading--split"><div><p class="rzu-eyebrow">Membership Access</p><h2 id="rzu-memberships-title">Start where the evidence says you are ready.</h2></div><a class="rzu-text-link" href="index.html#membership-access">Compare all features <span aria-hidden="true">→</span></a></header><div class="rzu-membership-grid">${membershipStrip}</div><div class="rzu-membership-disclaimer">Membership access is separate from academic admission and does not guarantee certification, assignments, employment, or advancement.</div></div></section>
<section class="rzu-journey-eligibility rzu-transition" aria-labelledby="rzu-journey-title"><div class="rzu-shell rzu-journey-eligibility__inner"><div class="rzu-journey-eligibility__visual"><img src="assets/sections/refzone-journey-ball.png" alt="A glowing blue-and-burnt-orange basketball" loading="lazy" decoding="async"></div><div class="rzu-journey-eligibility__content"><p class="rzu-journey-eligibility__eyebrow">YOUR JOURNEY STARTS HERE</p><h2 id="rzu-journey-title"><span>READY TO TAKE</span><span>THE NEXT STEP?</span></h2><p class="rzu-journey-eligibility__copy">Answer a few questions about your background and goals,<br>and RefZone University will recommend a competition track,<br>pathway, membership, and prerequisite route.</p><a class="rzu-journey-eligibility__cta" href="#/placement"><span>TAKE THE ELIGIBILITY SURVEY</span><svg aria-hidden="true" viewBox="0 0 20 20" focusable="false"><path d="M3 10h12M11 5l5 5-5 5"/></svg></a></div></div></section>
</div>`}
function chooseYourPathSection(){return `<section class="rzu-bundles rzu-bundles--catalog" aria-labelledby="rzu-bundles-title">
  <div class="rzu-shell rzu-bundles__frame">
    <header class="rzu-section-heading"><p class="rzu-eyebrow">CHOOSE YOUR PATH</p><h2 id="rzu-bundles-title">CURATED TRACK GROUPS. BUILT FOR YOUR GOALS.</h2><p>Explore related rulesets together while every course remains independently managed and connected to its own pathway.</p></header>
    <div class="rzu-bundle-grid">
      <article class="rzu-bundle-card"><div class="rzu-bundle-art"><img src="assets/pathway-icons/rfzu_nfhs.png" alt=""><img src="assets/pathway-icons/rfzu_njcaambb.png" alt=""><img src="assets/pathway-icons/rfzu_naiambb.png" alt=""></div><div class="rzu-bundle-card__body"><h3><span>Federation Development</span><b>NFHS / NJCAA / NAIA</b></h3><p>Build a connected domestic development route across high school, junior college, and NAIA competition.</p></div><strong>5 TRACKS</strong></article>
      <article class="rzu-bundle-card"><div class="rzu-bundle-art"><img src="assets/pathway-icons/rfzu_ncaadiiimbb.png" alt=""><img src="assets/pathway-icons/rfzu_ncaadiimbb.png" alt=""><img src="assets/pathway-icons/rfzu_ncaadimbb.png" alt=""></div><div class="rzu-bundle-card__body"><h3><span>NCAA Development</span><b>NCAA DIII / DII / DI</b></h3><p>Progress through collegiate pace, leadership, film, mechanics, and performance expectations.</p></div><strong>6 TRACKS</strong></article>
      <article class="rzu-bundle-card"><div class="rzu-bundle-art"><img src="assets/pathway-icons/rfzu_usambb.png" alt=""><img src="assets/pathway-icons/refzone_university_fiba_men_course.png" alt=""><img src="assets/pathway-icons/refzone_university_euro_league_men_course.png" alt=""></div><div class="rzu-bundle-card__body"><h3><span>Global Basketball</span><b>USA / FIBA / EURO</b></h3><p>Compare national and international rulesets while preserving event-specific requirements.</p></div><strong>6 TRACKS</strong></article>
      <article class="rzu-bundle-card"><div class="rzu-bundle-art"><img src="assets/pathway-icons/refzone_university_g_league_course.png" alt=""><img src="assets/pathway-icons/refzone_university_wnba_course.png" alt=""><img src="assets/pathway-icons/refzone_university_nba_course.png" alt=""></div><div class="rzu-bundle-card__body"><h3><span>Professional Development</span><b>G LEAGUE / WNBA / NBA</b></h3><p>Advanced educational preparation for qualified learners pursuing professional-development study.</p></div><strong>3 TRACKS</strong></article>
    </div>
    <div class="rzu-center-action"><button class="rzu-button rzu-button--secondary" type="button" data-scroll-catalog>COMPARE ALL TRACKS <span aria-hidden="true">→</span></button></div>
  </div>
</section>`}
function connectedPathwaysSection(){return `<section class="rzu-pathways rzu-pathways--catalog rzu-unified-catalog" id="catalog-directory" aria-labelledby="rzu-connected-pathways-title">
  <div class="rzu-shell">
    <header class="rzu-section-heading rzu-section-heading--split">
      <div><p class="rzu-eyebrow">ALL 60 PATHWAYS REMAIN CONNECTED</p><h2 id="rzu-connected-pathways-title">CHOOSE THE RULESET. CHOOSE THE STAGE.</h2><p>Every competition track links directly to Bachelor’s Foundations, Master’s Advancement, and PhD Elite study.</p></div>
      <span class="rzu-unified-catalog__count">20 TRACKS · 60 PATHWAYS</span>
    </header>
    <div class="filter-row rzu-catalog-filters" aria-label="Filter Programs and Pathways">
      <input id="catalogSearch" type="search" placeholder="Search tracks" aria-label="Search competition tracks">
      <select id="groupFilter" aria-label="Filter by track group"><option value="">All groups</option>${[...new Set(D.tracks.map(t=>t.group))].map(g=>`<option>${g}</option>`).join('')}</select>
      <select id="categoryFilter" aria-label="Filter by category"><option value="">All categories</option><option>Men</option><option>Women</option><option>Open</option></select>
    </div>
    <div class="grid three rzu-unified-catalog__grid" id="catalogGrid">${trackCards(D.tracks)}</div>
  </div>
</section>`}
function catalog(){return shell('Programs & Pathways',`<p class="muted">Programs and pathways are presented together in one catalog. Every competition level contains three independently managed degree structures: Bachelor’s Professional Foundations, Master’s Advanced Officiating, and PhD Research, Leadership, and Elite Officiating. Course publication remains blocked until controlling sources and human reviews are approved.</p>${chooseYourPathSection()}${connectedPathwaysSection()}`,'20 COMPETITION TRACKS · 60 PATHWAYS')}
function trackCards(list){return list.map(t=>`<article class="card track-card"><div class="track-icon-shell">${trackIcon(t,'track-icon-image')}</div><div class="meta"><span class="pill">${t.group}</span><span class="pill">${t.category}</span></div><h3>${t.name}</h3><p>${t.sourceStatus}</p><div class="track-degree-links"><a href="#/program/${t.id}/foundations"><strong>Bachelor’s</strong><small>24 courses · 120 units</small></a><a href="#/program/${t.id}/advancement"><strong>Master’s</strong><small>12 courses · 36 units</small></a><a href="#/program/${t.id}/elite"><strong>PhD</strong><small>20 courses · 60 units</small></a></div></article>`).join('')||`<div class="empty-state"><strong>No matching tracks</strong><p>Change the catalog filters.</p></div>`}
function program(trackId,pathId){
const t=getTrack(trackId),p=getPath(pathId),courseUI=getCourseUI(trackId,pathId),C=courseUI?.course||null;
const plan=window.RefZoneDegreeFramework.build(C,t,p.id);
const sourceRegistry=C?.sourceRegistry?.length?`<section class="section"><div class="section-head"><div><p class="eyebrow">SOURCE CONTROL</p><h2>Current reference registry</h2></div></div><div class="grid three">${C.sourceRegistry.map(x=>`<article class="card"><div class="meta"><span class="pill orange">${x.season}</span><span class="pill">${x.type}</span></div><h3>${x.title}</h3><p>${x.status}</p></article>`).join('')}</div></section>`:'';
return shell(`${t.name}: ${plan.degree}`,`${window.RefZoneDegreeFramework.programMarkup(plan,t.sourceStatus,`#/course/${t.id}/${p.id}`)}${sourceRegistry}`,`${t.name.toUpperCase()} · ${plan.degree.toUpperCase()} DEGREE STRUCTURE`)}

function course(trackId,pathId,lessonId){const courseUI=getCourseUI(trackId,pathId);if(courseUI)return courseUI.render({lessonId});const t=getTrack(trackId),p=getPath(pathId),mods=D.curriculum[p.id],completed=store.get('completed',{});return `<section class="course-shell"><aside class="course-sidebar"><p class="eyebrow">${esc(t.name)}</p><h2>${esc(p.short)}</h2><div class="notice">This pathway is scheduled for source validation and course production.</div><div style="margin-top:16px">${mods.map((m,i)=>`<div class="module"><button data-module="${i}">${i+1}. ${esc(m)}</button><div class="lessons"><label class="lesson-row"><input type="checkbox" data-complete="${trackId}:${pathId}:${i}" ${completed[`${trackId}:${pathId}:${i}`]?'checked':''}> Curriculum item</label></div></div>`).join('')}</div></aside><main class="course-main"><div class="course-topbar"><div><p class="eyebrow">COURSE LEARNING INTERFACE</p><h1>${esc(t.name)} — ${esc(p.short)}</h1></div><a class="button secondary" href="#/program/${t.id}/${p.id}">Program overview</a></div><div class="empty-state"><strong>Course production has not started</strong><p>The complete NFHS Bachelor’s, Master’s, and PhD classrooms and the complete NJCAA Men’s Bachelor’s, Master’s, and PhD classrooms and the complete NJCAA Women’s Bachelor’s classroom are active course builds. This selected pathway will be produced in sequence under the master course-generation system.</p></div></main></section>`}
const surveySteps=[
{title:'Your officiating goal',html:`<div class="field"><label for="goal">Primary goal</label><select id="goal" name="goal" required><option value="">Select</option><option>Learn officiating fundamentals</option><option>Develop toward a higher competition level</option><option>Evaluator, instructor, or leadership development</option><option>Research and policy development</option></select></div><div class="field"><label for="role">Current role</label><select id="role" name="role" required><option value="new">New or prospective official</option><option value="active">Active official</option><option value="returning">Returning official</option><option value="leader">Observer, evaluator, assignor, instructor, or administrator</option></select></div>`},
{title:'Current experience',html:`<div class="field"><label for="years">Total years officiating</label><input id="years" name="years" type="number" min="0" max="60" value="0"></div><div class="field"><label for="games">Approximate games during the previous season</label><input id="games" name="games" type="number" min="0" max="500" value="0"></div><div class="field"><label for="track">Primary current or desired ruleset</label><select id="track" name="track">${D.tracks.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</select></div><label class="choice"><input name="multiple" type="checkbox"> I actively need multiple rulesets</label>`},
{title:'Rules and mechanics background',html:`<div class="field"><fieldset><legend>Experience areas</legend><label class="choice"><input type="checkbox" name="threePerson"> Three-person mechanics</label><label class="choice"><input type="checkbox" name="crewChief"> Crew-chief responsibility</label><label class="choice"><input type="checkbox" name="replay"> Replay or monitor procedures</label><label class="choice"><input type="checkbox" name="evaluation"> Evaluation or instruction</label></fieldset></div>`},
{title:'Knowledge diagnostic',html:`${q('q1','Before relying on a rule publication, what must be verified?',['That it appears first in a search result','Its governing body, version, effective date, and approval status','That another official remembers it','That it is the newest file name'],'1')}${q('q2','A newly published rulebook has a future effective date. Which version controls today?',['The newly published version immediately','The current effective version until the stated effective date','Whichever version is shorter','Both versions at the same time'],'1')}${q('q3','A rules question is disputed during curriculum review. What should happen?',['Publish the most popular answer','Hide the source conflict','Pause publication and route it to an authorized reviewer','Allow each student to choose'],'2')}`},
{title:'Video and case-play diagnostic',html:`<div class="notice">These are original workflow scenarios, not official rule interpretations.</div>${q('q4','During film review, which sequence best supports a defensible ruling?',['Choose a result first, then find a clip','Identify the action, responsible official, applicable source, ruling, and rationale','Rely only on crowd reaction','Use confidence alone'],'1')}${q('q5','A clip does not show the complete play. What is the best review action?',['Invent the missing action','Issue a final ruling anyway','Mark the evidence incomplete and request another angle or advisor review','Ignore the limitation'],'2')}`},
{title:'Leadership and professional goals',html:`${q('q6','A crew has a double whistle. Which response best supports professional communication?',['Compete to report first','Use calm crew communication, identify responsibilities, and resolve the ruling','Avoid speaking to partners','Let the loudest person decide'],'1')}${q('q7','A clock discrepancy is discovered. What is the best first process?',['Guess a correction','Consult the crew, table personnel, and available official information','Ask spectators','Ignore it'],'1')}<label class="choice"><input type="checkbox" name="research"> I am prepared for advanced independent research or a capstone.</label>`},
{title:'Review and recommendation',html:`<p>Review your entries, then calculate a deterministic recommendation. Your total score is combined with prerequisite gates. Membership access is not academic admission and does not guarantee assignments, certification, employment, or professional advancement.</p><label class="choice"><input type="checkbox" name="consent" required> Save my survey result in this browser for the recommendation workflow.</label>`}
];
function q(name,text,opts,correct){return `<fieldset class="field"><legend>${text}</legend>${opts.map((o,i)=>`<label class="choice"><input type="radio" name="${name}" value="${i}" required> ${o}</label>`).join('')}<input type="hidden" data-correct="${name}" value="${correct}"></fieldset>`}
function placement(){const saved=store.get('survey',{});return shell('Placement survey',`<div class="survey-shell"><div class="card"><div style="display:flex;justify-content:space-between;gap:12px"><strong id="stepLabel">Step 1 of ${surveySteps.length}</strong><span class="muted">Estimated 8–12 minutes</span></div><div class="progress-track" aria-label="Survey progress"><div class="progress-fill" id="surveyProgress" style="width:${100/surveySteps.length}%"></div></div><form id="placementForm"><div class="survey-step" id="surveyStep"></div><div class="survey-actions"><button type="button" class="button secondary" id="surveyBack">Back</button><button type="button" class="button ghost" id="surveySave">Save and return</button><button type="button" class="button" id="surveyNext">Continue</button></div></form></div></div>`,'ADAPTIVE STARTING-POINT REVIEW')}
function calculateRecommendation(fd){let rules=0,mech=0,video=0,game=0,experience=0,leadership=0;['q1','q2','q3'].forEach((k,i)=>{const correct=['1','1','2'][i];if(fd.get(k)===correct)rules+=25/3});if(fd.get('q6')==='1')mech+=20;if(fd.get('q4')==='1')video+=10;if(fd.get('q5')==='2')video+=10;if(fd.get('q7')==='1')game+=15;const years=Number(fd.get('years')||0),games=Number(fd.get('games')||0);experience=Math.min(10,years*1.2+games/50);if(fd.get('crewChief'))leadership+=3;if(fd.get('evaluation'))leadership+=4;if(fd.get('research'))leadership+=3;const total=Math.round(rules+mech+video+game+experience+leadership);let membership='foundations';const gaps=[];if(years===0||rules<15||mech<12){membership='foundations';gaps.push('Foundational rules or mechanics prerequisite');}else if(total>=80&&leadership>=6&&years>=5)membership='elite';else if(total>=55)membership='advancement';if(fd.get('multiple')||fd.get('role')==='leader')membership='all-access';const p=membership==='all-access'?(total>=80?'elite':total>=55?'advancement':'foundations'):membership;const rec={id:crypto.randomUUID(),createdAt:Date.now(),expiresAt:Date.now()+7*86400000,track:fd.get('track')||'nfhs',membership,pathway:p,score:total,categories:{'Rules knowledge':Math.round(rules),'Mechanics and positioning':Math.round(mech),'Video judgment':Math.round(video),'Game management':Math.round(game),'Verified experience readiness':Math.round(experience),'Leadership and research':Math.round(leadership)},gaps,confidence:(rules+video+game)>=40?'High':'Moderate',reasons:[`Objective diagnostic score: ${Math.round(rules+mech+video+game)} of 80`,`Experience readiness score: ${Math.round(experience)} of 10`,`Leadership and research score: ${Math.round(leadership)} of 10`]};store.set('recommendation',rec);return rec}
function recommendation(){const r=store.get('recommendation');if(!r)return shell('No recommendation available',`<div class="empty-state"><strong>Complete the placement survey</strong><p>A secure browser-local recommendation record has not been created.</p><a class="button" href="#/placement">Take placement survey</a></div>`);const t=getTrack(r.track),m=D.memberships.find(x=>x.id===r.membership),p=getPath(r.pathway);return shell('Your RefZone Starting Recommendation',`<div class="program-layout"><div><article class="card membership-card recommended"><span class="recommended-label">RECOMMENDED FOR YOUR PLACEMENT</span><p class="eyebrow">${t.name}</p><h2>${m.name}</h2><div class="price">$${m.monthly}<small>/month</small></div><p>${p.title}</p><p>Placement confidence: <strong>${r.confidence}</strong> · Score: <strong>${r.score}/100</strong></p><div class="score-grid">${Object.entries(r.categories).map(([k,v])=>`<div class="score-card"><strong>${v}</strong><div>${k}</div></div>`).join('')}</div></article><section class="section"><h2>Why this starting point</h2><div class="list">${r.reasons.map((x,i)=>`<div class="list-item"><span class="number">${i+1}</span><span>${x}</span></div>`).join('')}</div>${r.gaps.length?`<h3>Prerequisite development</h3><ul class="feature-list">${r.gaps.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}</section></div><aside class="card sticky-card"><h3>${m.name}</h3><p>${m.intended}</p><ul class="feature-list">${m.features.map(x=>`<li>${x}</li>`).join('')}</ul><div class="list"><a class="button" href="index.html#membership-access">View membership access</a><a class="button secondary" href="#/placement">Retake survey</a><button class="button ghost" data-advisor-review>Request advisor review</button></div></aside></div>`,'PERSONALIZED RECOMMENDATION')}
function membership(){const r=store.get('recommendation');return window.RefZoneMembershipRegistration?window.RefZoneMembershipRegistration.renderComparison(D.memberships,r):shell('Membership comparison','<div class="empty-state"><strong>Membership registration unavailable</strong></div>','ACCESS PLANS')}
function checkout(planId){const m=D.memberships.find(x=>x.id===planId)||D.memberships[0],r=store.get('recommendation'),t=getTrack(r?.track||'nfhs');const body=window.RefZoneMembershipRegistration?window.RefZoneMembershipRegistration.render({membership:m,recommendation:r,track:t,tracks:D.tracks,pathways:D.pathways}):'<div class="empty-state"><strong>Registration interface unavailable</strong></div>';return shell('Membership registration',body,'SECURE MEMBERSHIP ENROLLMENT')}
function dashboard(){const e=store.get('enrollment');return shell('Student dashboard',`<div class="dashboard-layout"><nav class="card dashboard-nav"><a href="#/dashboard">Overview</a><a href="#/catalog">Programs &amp; Pathways</a><a href="#/course/${e?.track||'nfhs'}/${e?.pathway||'foundations'}">Continue learning</a><a href="#/notifications">Notifications</a><a href="index.html#membership-access">Membership access</a></nav><div>${e?`<div class="metric-row"><div class="metric"><span class="muted">Membership</span><strong>${D.memberships.find(m=>m.id===e.plan)?.name}</strong></div><div class="metric"><span class="muted">Competition track</span><strong>${getTrack(e.track).name}</strong></div><div class="metric"><span class="muted">Progress</span><strong>${progressPercent(e.track,e.pathway)}%</strong></div><div class="metric"><span class="muted">Credential status</span><strong>Not issued</strong></div></div><section class="section"><div class="section-head"><div><p class="eyebrow">CONTINUE LEARNING</p><h2>Orientation and first pathway</h2></div></div><article class="card"><span class="pill orange">${getTrack(e.track).name}</span><h3>${getPath(e.pathway).title}</h3><p>Open the course workspace and upload an approved lesson video to the iPad player.</p><a class="button" href="#/course/${e.track}/${e.pathway}">Continue learning</a></article></section>`:`<div class="empty-state"><strong>No active enrollment</strong><p>Complete the placement survey or select a membership to create your learning plan.</p><a class="button" href="#/placement">Find my starting point</a></div>`}</div></div>`,'STUDENT PORTAL')}
function progressPercent(track,path){const mods=D.curriculum[path]||[],c=store.get('completed',{}),n=mods.filter((_,i)=>c[`${track}:${path}:${i}`]).length;return mods.length?Math.round(n/mods.length*100):0}
function instructor(){return shell('Instructor dashboard',`<div class="metric-row"><div class="metric"><span class="muted">Published courses</span><strong>0</strong></div><div class="metric"><span class="muted">Pending submissions</span><strong>0</strong></div><div class="metric"><span class="muted">Live sessions</span><strong>0</strong></div><div class="metric"><span class="muted">At-risk alerts</span><strong>0</strong></div></div><section class="section"><div class="grid three"><div class="empty-state"><strong>No courses assigned</strong><p>An administrator can invite an instructor and assign approved courses.</p><button class="button ghost">Request course access</button></div><div class="empty-state"><strong>No submissions yet</strong><p>Student work appears after enrollment and assignment submission.</p></div><div class="empty-state"><strong>No office hours scheduled</strong><p>Create availability after instructor permissions are approved.</p></div></div></section>`,'AUTHORIZED FACULTY WORKSPACE')}
function admin(){const memberships=store.get('memberships',D.memberships);return shell('Administrative CMS',`<div class="notice">This browser-local CMS demonstrates content control. Production use requires authenticated server-side roles, row-level security, audit logging, and a connected database.</div><div class="admin-tabs"><button data-admin-tab="memberships">Memberships</button><button data-admin-tab="programs">Programs</button><button data-admin-tab="sources">Source registry</button><button data-admin-tab="users">Roles</button><button data-admin-tab="audit">Audit log</button></div><div id="adminPanel">${membershipAdmin(memberships)}</div>`,'PLATFORM ADMINISTRATION')}
function membershipAdmin(ms){return `<form id="membershipAdminForm"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Monthly</th><th>Annual</th><th>Status</th></tr></thead><tbody>${ms.map(m=>`<tr><td><input name="name:${m.id}" value="${esc(m.name)}"></td><td><input type="number" min="0" name="monthly:${m.id}" value="${m.monthly}"></td><td><input type="number" min="0" name="annual:${m.id}" value="${m.annual??0}"></td><td><span class="pill orange">Editable</span></td></tr>`).join('')}</tbody></table></div><div class="hero-actions"><button class="button" type="submit">Save membership settings</button><button class="button secondary" type="button" data-reset-memberships>Reset launch settings</button></div></form>`}
function generic(title,text){return shell(title,`<div class="card"><p>${text}</p><div class="empty-state"><strong>Content not yet entered</strong><p>An authorized administrator can create and publish this page through the CMS.</p><a class="button ghost" href="#/admin">Open CMS</a></div></div>`)}
function roleDashboard(role){return shell(role+' dashboard',`<div class="notice">Access to this workspace requires the corresponding production role and server-side authorization.</div><section class="section"><div class="grid three"><div class="empty-state"><strong>No assigned records</strong><p>Records appear after authorized assignment.</p></div><div class="empty-state"><strong>No pending actions</strong><p>Workflow tasks will be listed here.</p></div><div class="empty-state"><strong>No reports available</strong><p>Reports require connected production data.</p></div></div></section>`,`AUTHORIZED ${role.toUpperCase()} WORKSPACE`)}
function login(){return shell('Sign in',`<div class="survey-shell"><form class="card" id="loginForm"><div class="field"><label>Email</label><input type="email" required autocomplete="email"></div><div class="field"><label>Password</label><input type="password" required autocomplete="current-password"></div><div class="notice">Authentication is not connected in this static package. The production schema and environment template are included.</div><button class="button" type="submit">Open demonstration dashboard</button></form></div>`,'SECURE ACCOUNT ACCESS')}
function render(){const parts=(location.hash.replace(/^#\/?/,'')||'home').split('/');if(parts[0]==='membership'){location.href='index.html#membership-access';return}document.body.classList.toggle('rzu-course-route',parts[0]==='course');let html='';switch(parts[0]){case'home':html=home();break;case'catalog':html=catalog();break;case'program':html=program(parts[1],parts[2]);break;case'course':html=course(parts[1],parts[2],parts[3]);break;case'placement':html=placement();break;case'recommendation':html=recommendation();break;case'checkout':html=checkout(parts[1]);break;case'dashboard':html=dashboard();break;case'instructor':html=instructor();break;case'admin':html=admin();break;case'login':html=login();break;case'about':html=generic('About RefZone University','A basketball-officiating education, assessment, leadership, and research ecosystem.');break;case'faculty':html=generic('Faculty','Faculty records remain empty until authorized instructors are invited and approved.');break;case'admissions':html=generic('Admissions','Academic admission is separate from membership access and requires verified program authority and published requirements.');break;case'tuition':html=generic('Tuition and financial information','Academic tuition, membership pricing, scholarships, taxes, and payment schedules are managed separately.');break;case'scholarships':html=generic('Scholarships','No scholarship programs have been published.');break;case'calendar':html=generic('Academic calendar','No academic dates have been entered.');break;case'research':html=generic('Research','Research publication requires source, ethics, peer-review, licensing, and program approvals.');break;case'resources':html=generic('Student resources','Student support resources can be added through the CMS.');break;case'technical':html=generic('Technical requirements','Production browser, device, bandwidth, caption, upload, and security requirements must be published before launch.');break;case'faq':html=generic('Frequently asked questions','No questions have been published.');break;case'contact':html=generic('Contact','No public contact channels have been configured.');break;case'register':html=generic('Registration','Registration is connected to the membership and admissions workflows.');break;case'application':html=generic('Application','Academic applications require a connected admissions database and document workflow.');break;case'applicant':html=roleDashboard('Applicant');break;case'advisor':html=roleDashboard('Academic advisor');break;case'evaluator':html=roleDashboard('Evaluator');break;case'registrar':html=roleDashboard('Registrar');break;case'financial':html=roleDashboard('Financial administrator');break;case'program-director':html=roleDashboard('Program director');break;case'super-admin':html=roleDashboard('Super administrator');break;case'accreditation':html=generic('Accreditation and credential status','Programs must use administrator-approved professional-pathway wording unless verified degree-granting authority, accreditation, or an authorized university partnership is documented.');break;case'accessibility':html=generic('Accessibility','The interface is structured for keyboard navigation, visible focus, semantic controls, reduced motion, scalable text, caption-ready video, and WCAG 2.2 AA implementation.');break;case'privacy':html=generic('Privacy Notice — Draft for Legal Review','RefZone University collects account, profile, learning-plan, consent, and billing-status information needed to administer membership. Payment credentials are collected and tokenized by Stripe and are not stored by RefZone University. Production launch requires finalized retention, deletion, data-subject-rights, cookie, international-transfer, and service-provider disclosures.');break;case'terms':html=generic('Terms of Membership — Draft for Legal Review','Paid memberships renew automatically at the selected billing interval until canceled. Membership access is separate from academic admission and does not guarantee governing-body registration, certification, assignments, employment, or advancement. Live checkout must remain disabled until these terms, cancellation mechanics, governing law, dispute provisions, and customer-support contacts are approved.');break;case'refund':html=generic('Refund and Cancellation Policy — Approval Required','The payment gateway is designed to disclose the amount charged today, renewal interval, taxes, discounts, and cancellation terms before authorization. A binding refund policy has not been supplied in the project materials. Live payment mode must remain disabled until an authorized RefZone University administrator and legal reviewer publish the final refund and cancellation policy.');break;case'notifications':html=generic('Notifications','No notifications are available. Production channels may include in-platform, email, push, and optional SMS.');break;default:html=generic('Page not found','The requested route is not available.');}app.innerHTML=html;wire(parts);app.focus({preventScroll:true});window.scrollTo(0,0)}
function wire(parts){if(parts[0]==='catalog'){const update=()=>{const q=document.getElementById('catalogSearch').value.toLowerCase(),g=document.getElementById('groupFilter').value,c=document.getElementById('categoryFilter').value;document.getElementById('catalogGrid').innerHTML=trackCards(D.tracks.filter(t=>t.name.toLowerCase().includes(q)&&(!g||t.group===g)&&(!c||t.category===c)))};['catalogSearch','groupFilter','categoryFilter'].forEach(id=>document.getElementById(id).addEventListener('input',update));document.querySelectorAll('[data-scroll-catalog]').forEach(button=>button.addEventListener('click',()=>document.getElementById('catalog-directory')?.scrollIntoView({behavior:'smooth',block:'start'})))}
if(parts[0]==='course'){const courseUI=getCourseUI(parts[1],parts[2]);if(courseUI){courseUI.wire({lessonId:parts[3],showToast})}else{document.querySelectorAll('[data-complete]').forEach(x=>x.addEventListener('change',()=>{const c=store.get('completed',{});c[x.dataset.complete]=x.checked;store.set('completed',c);showToast('Lesson progress saved')}))}}
if(parts[0]==='placement')setupSurvey();if(parts[0]==='checkout'){const membership=D.memberships.find(x=>x.id===parts[1])||D.memberships[0];window.RefZoneMembershipRegistration?.mount({membership,recommendation:store.get('recommendation'),tracks:D.tracks,pathways:D.pathways})};if(parts[0]==='admin'){wireAdmin()}if(parts[0]==='login')document.getElementById('loginForm').addEventListener('submit',e=>{e.preventDefault();route('dashboard')});document.querySelector('[data-advisor-review]')?.addEventListener('click',()=>showToast('Advisor review request saved locally'))}
function setupSurvey(){let step=0;const form=document.getElementById('placementForm'),panel=document.getElementById('surveyStep');const saved=store.get('survey',{});const draw=()=>{panel.innerHTML=`<p class="eyebrow">STEP ${step+1}</p><h2>${surveySteps[step].title}</h2>${surveySteps[step].html}`;Object.entries(saved).forEach(([k,v])=>{const els=form.querySelectorAll(`[name="${CSS.escape(k)}"]`);els.forEach(el=>{if(el.type==='checkbox'||el.type==='radio')el.checked=Array.isArray(v)?v.includes(el.value):v===el.value||v===true;else el.value=v})});document.getElementById('stepLabel').textContent=`Step ${step+1} of ${surveySteps.length}`;document.getElementById('surveyProgress').style.width=`${(step+1)/surveySteps.length*100}%`;document.getElementById('surveyBack').disabled=step===0;document.getElementById('surveyNext').textContent=step===surveySteps.length-1?'Calculate recommendation':'Continue'};const save=()=>{new FormData(form).forEach((v,k)=>saved[k]=v);form.querySelectorAll('input[type=checkbox]').forEach(x=>saved[x.name]=x.checked);store.set('survey',saved)};document.getElementById('surveySave').onclick=()=>{save();showToast('Survey progress saved')};document.getElementById('surveyBack').onclick=()=>{save();step=Math.max(0,step-1);draw()};document.getElementById('surveyNext').onclick=()=>{if(!form.reportValidity())return;save();if(step<surveySteps.length-1){step++;draw()}else{const data=new FormData();Object.entries(saved).forEach(([k,v])=>{if(v===true)data.set(k,'on');else if(v!==false)data.set(k,v)});calculateRecommendation(data);route('recommendation')}};draw()}
function wireAdmin(){document.getElementById('membershipAdminForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),ms=structuredClone(D.memberships);ms.forEach(m=>{m.name=f.get('name:'+m.id);m.monthly=Number(f.get('monthly:'+m.id));m.annual=Number(f.get('annual:'+m.id))||null});store.set('memberships',ms);D.memberships.splice(0,D.memberships.length,...ms);const log=store.get('audit',[]);log.unshift({time:new Date().toISOString(),action:'Membership settings updated'});store.set('audit',log);showToast('Membership settings saved')});document.querySelector('[data-reset-memberships]')?.addEventListener('click',()=>{localStorage.removeItem('rz:memberships');showToast('Launch settings restored');render()});document.querySelectorAll('[data-admin-tab]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.adminTab,p=document.getElementById('adminPanel');if(id==='memberships')p.innerHTML=membershipAdmin(store.get('memberships',D.memberships));if(id==='programs')p.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Track</th><th>Pathways</th><th>Source status</th><th>Accreditation label</th></tr></thead><tbody>${D.tracks.map(t=>`<tr><td>${t.name}</td><td>3</td><td>${t.sourceStatus}</td><td>${t.status}</td></tr>`).join('')}</tbody></table></div>`;if(id==='sources')p.innerHTML=`<div class="empty-state"><strong>No source publications indexed</strong><p>The Rules(1).zip archive referenced in the specification was not included with the current uploaded files. Add source files, checksums, licensing, effective dates, and review status before publication.</p><button class="button ghost">Add source publication</button></div>`;if(id==='users')p.innerHTML=`<div class="card"><h3>Role-based access control</h3><p class="muted">Prospective student, applicant, student, teaching assistant, instructor, faculty chair, academic advisor, evaluator, proctor, registrar, financial administrator, program director, content editor, support representative, platform administrator, and super administrator.</p></div>`;if(id==='audit'){const a=store.get('audit',[]);p.innerHTML=a.length?`<div class="list">${a.map(x=>`<div class="list-item"><span class="number">•</span><div><strong>${x.action}</strong><div class="muted">${x.time}</div></div></div>`).join('')}</div>`:`<div class="empty-state"><strong>No administrative changes logged</strong><p>CMS changes will appear here.</p></div>`}wireAdmin()}))}
function updatePlatformNavigation(){
  const routeName=(location.hash.replace(/^#\/?/, '').split('/')[0]||'home');
  document.querySelectorAll('[data-platform-nav]').forEach(link=>link.classList.remove('active'));
  const key=routeName==='catalog'?'programs':routeName==='placement'||routeName==='recommendation'?'placement':routeName==='checkout'?'none':routeName==='course'||routeName==='program'?'learning':routeName==='login'||routeName==='dashboard'||routeName==='instructor'||routeName==='advisor'||routeName==='admin'||routeName==='registrar'||routeName==='financial'||routeName==='program-director'||routeName==='super-admin'?'account':'home';
  document.querySelectorAll(`[data-platform-nav="${key}"]`).forEach(link=>link.classList.add('active'));
}
const dlg=document.getElementById('searchDialog'),search=document.getElementById('globalSearch'),searchButton=document.getElementById('searchButton');
if(dlg&&search&&searchButton){
  searchButton.onclick=()=>{dlg.showModal();setTimeout(()=>search.focus(),0)};
  search.addEventListener('input',()=>{const q=search.value.toLowerCase(),items=[...D.tracks.flatMap(t=>D.pathways.map(p=>({title:`${t.name} ${p.short}`,route:`program/${t.id}/${p.id}`,type:`${p.short} degree structure`}))),...D.pathways.map(p=>({title:p.title,route:'catalog',type:'Degree structure'})),{title:'Placement survey',route:'placement',type:'Tool'},{title:'Membership access',href:'index.html#membership-access',type:'Page'},{title:'Student dashboard',route:'dashboard',type:'Portal'},{title:'Administrative CMS',route:'admin',type:'Portal'}].filter(x=>x.title.toLowerCase().includes(q)).slice(0,12);document.getElementById('searchResults').innerHTML=items.map(x=>`<a class="search-result" href="${x.href||`#/${x.route}`}" onclick="document.getElementById('searchDialog').close()"><strong>${x.title}</strong><div class="muted">${x.type}</div></a>`).join('')});
}
window.addEventListener('hashchange',()=>{render();updatePlatformNavigation()});render();updatePlatformNavigation();
})();
